import { beforeEach, describe, expect, it } from 'vitest';
import { SlateInstanceOAuthSetupStatus } from '../../../../prisma/generated/client';
import { slatesHubClient } from '../../../test/client';
import { fixtures } from '../../../test/fixtures';
import { cleanDatabase, testDb } from '../../../test/setup';

describe('slateOAuthSetup:list E2E', () => {
  const f = fixtures(testDb);

  beforeEach(async () => {
    await cleanDatabase();
  });

  it('returns OAuth setups for a tenant', async () => {
    const { setup, tenant, slate, credentials, authMethod } =
      await f.slateOAuthSetup.complete();

    await f.slateOAuthSetup.withSecret({
      tenantOid: tenant.oid,
      slateOid: slate.oid,
      slateVersionOid: slate.currentVersion.oid,
      authMethodOid: authMethod.oid,
      oauthCredentialsOid: credentials.oid
    });

    const result = await slatesHubClient.slateOAuthSetup.list({
      tenantId: tenant.id,
      limit: 10
    });

    expect(result.items).toHaveLength(2);
    expect(result.items[0]).toMatchObject({
      id: setup.id,
      slateId: slate.id,
      status: SlateInstanceOAuthSetupStatus.unused,
      redirectUrl: setup.redirectUrl,
      url: expect.any(String),
      error: null,
      credentials: {
        id: credentials.id
      },
      authConfig: null,
      createdAt: expect.any(Date),
      updatedAt: expect.any(Date)
    });
  });

  it('filters by slateIds', async () => {
    const {
      setup: setup1,
      tenant,
      slate: slate1
    } = await f.slateOAuthSetup.complete({
      slateIdentifier: 'slate-1'
    });

    await f.slateOAuthSetup.complete({
      slateIdentifier: 'slate-2'
    });

    const result = await slatesHubClient.slateOAuthSetup.list({
      tenantId: tenant.id,
      slateIds: [slate1.id],
      limit: 10
    });

    expect(result.items).toHaveLength(1);
    expect(result.items[0]!.id).toBe(setup1.id);
  });
});

describe('slateOAuthSetup:get E2E', () => {
  const f = fixtures(testDb);

  beforeEach(async () => {
    await cleanDatabase();
  });

  it('returns a single OAuth setup by ID', async () => {
    const { setup, tenant, slate } = await f.slateOAuthSetup.complete({
      status: SlateInstanceOAuthSetupStatus.unused
    });

    const result = await slatesHubClient.slateOAuthSetup.get({
      tenantId: tenant.id,
      slateOAuthSetupId: setup.id
    });

    expect(result).toMatchObject({
      id: setup.id,
      slateId: slate.id,
      status: SlateInstanceOAuthSetupStatus.unused
    });
  });
});

describe('slateOAuthSetup:getLogs E2E', () => {
  const f = fixtures(testDb);

  beforeEach(async () => {
    await cleanDatabase();
  });

  it('returns logs for an OAuth setup', async () => {
    const { setup, slate, tenant } = await f.slateOAuthSetup.complete();

    const result = await slatesHubClient.slateOAuthSetup.getLogs({
      tenantId: tenant.id,
      slateOAuthSetupId: setup.id
    });

    expect(result).toMatchObject({
      id: setup.id,
      slateId: slate.id,
      error: null,
      events: []
    });
  });
});

describe('slateOAuthSetup:getMany E2E', () => {
  const f = fixtures(testDb);

  beforeEach(async () => {
    await cleanDatabase();
  });

  it('returns multiple OAuth setups by IDs', async () => {
    const tenant = await f.tenant.default();
    const slate = await f.slate.complete();
    const authMethod = await f.slateAuthMethod.default({
      slateOid: slate.oid,
      specificationOid: slate.currentVersion.specification.oid
    });
    const credsSecret = await f.secret.default({ tenantOid: tenant.oid });
    const credentials = await f.slateOAuthCredentials.default({
      slateOid: slate.oid,
      tenantOid: tenant.oid,
      secretOid: credsSecret.oid
    });

    const setup1 = await f.slateOAuthSetup.withSecret({
      tenantOid: tenant.oid,
      slateOid: slate.oid,
      slateVersionOid: slate.currentVersion.oid,
      authMethodOid: authMethod.oid,
      oauthCredentialsOid: credentials.oid
    });
    const setup2 = await f.slateOAuthSetup.withSecret({
      tenantOid: tenant.oid,
      slateOid: slate.oid,
      slateVersionOid: slate.currentVersion.oid,
      authMethodOid: authMethod.oid,
      oauthCredentialsOid: credentials.oid
    });

    const result = await slatesHubClient.slateOAuthSetup.getMany({
      tenantId: tenant.id,
      slateOAuthSetupIds: [setup1.id, setup2.id]
    });

    expect(result).toMatchObject([{ id: setup1.id }, { id: setup2.id }]);
  });
});

import { beforeEach, describe, expect, it, vi } from 'vitest';

let {
  authBlockService,
  db,
  deviceService,
  exchangeCodeForData,
  markAresUserChanged,
  sendAuthCodeEmail,
  userService
} = vi.hoisted(() => ({
  authBlockService: { registerBlock: vi.fn() },
  db: {
    accountDomain: { findUnique: vi.fn() },
    app: { findUnique: vi.fn() },
    appOAuthProvider: { findFirst: vi.fn() },
    authDevice: { findUnique: vi.fn() },
    authIntent: { create: vi.fn(), update: vi.fn(), updateMany: vi.fn() },
    authIntentCode: { create: vi.fn() },
    authIntentStep: { create: vi.fn() },
    ssoConnection: { findMany: vi.fn() },
    user: { findFirst: vi.fn(), findUnique: vi.fn() },
    userIdentity: {
      create: vi.fn(),
      findFirst: vi.fn(),
      findUnique: vi.fn(),
      update: vi.fn(),
      updateMany: vi.fn()
    },
    userIdentityProvider: { findFirst: vi.fn() }
  },
  deviceService: { checkIfUserIsLoggedIn: vi.fn() },
  exchangeCodeForData: vi.fn(),
  markAresUserChanged: vi.fn(),
  sendAuthCodeEmail: { send: vi.fn() },
  userService: { findByEmailSafe: vi.fn(), linkToAccount: vi.fn() }
}));

vi.mock('@lowerdeck/service', () => ({
  Service: {
    create: vi.fn((_name: string, factory: () => unknown) => ({
      build: () => factory()
    }))
  }
}));

vi.mock('../db', () => ({
  db,
  withTransaction: async (cb: (tdb: unknown) => Promise<unknown>) => await cb(db)
}));

vi.mock('../email/authCode', () => ({
  sendAuthCodeEmail
}));

vi.mock('../email/successfulLogin', () => ({
  successfulLoginVerification: { send: vi.fn() }
}));

vi.mock('../lib/socials', () => ({
  socials: {
    google: { exchangeCodeForData },
    github: { exchangeCodeForData }
  }
}));

vi.mock('../queues/syncCallback', () => ({
  markAresUserChanged
}));

vi.mock('./accessGroup', () => ({ accessGroupService: {} }));
vi.mock('./auditLog', () => ({ auditLogService: { log: vi.fn() } }));
vi.mock('./authBlock', () => ({ authBlockService }));
vi.mock('./device', () => ({ deviceService }));
vi.mock('./sso/domainPolicy', () => ({ ssoDomainPolicyService: {} }));
vi.mock('./user', () => ({ userService }));

import { authService } from './auth';

describe('authService.authWithSocialProviderToken', () => {
  let app = { oid: 3n } as any;
  let user = { oid: 8n, id: 'usr_1', appOid: app.oid } as any;

  beforeEach(() => {
    vi.clearAllMocks();
    db.authIntent.updateMany.mockResolvedValue({ count: 1 });
    db.appOAuthProvider.findFirst.mockResolvedValue({
      oid: 1n,
      clientId: 'client',
      clientSecret: 'secret',
      redirectUri: 'https://example.com/callback'
    });
    db.accountDomain.findUnique.mockResolvedValue(null);
    db.app.findUnique.mockResolvedValue({ ...app, disableEmailAuth: false });
    db.ssoConnection.findMany.mockResolvedValue([]);
    db.user.findFirst.mockResolvedValue(null);
    db.userIdentityProvider.findFirst.mockResolvedValue({ oid: 4n });
    db.userIdentity.findFirst.mockResolvedValue(null);
    db.userIdentity.create.mockResolvedValue({
      oid: 5n,
      id: 'uid_1',
      userOid: null,
      email: 'victim@example.com'
    });
    db.authIntent.create.mockImplementation(async ({ data }) => ({ ...data, oid: 6n }));
    db.authIntentStep.create.mockImplementation(async ({ data }) => ({ ...data, oid: 7n }));
    db.authIntentCode.create.mockImplementation(async ({ data }) => ({ ...data, oid: 9n }));
    userService.findByEmailSafe.mockResolvedValue(user);
  });

  it.each([false, undefined])(
    'requires an email code when provider verification state is %s',
    async emailVerified => {
      exchangeCodeForData.mockResolvedValue({
        id: 'attacker@provider.example',
        email: 'victim@example.com',
        emailVerified,
        name: 'Attacker',
        token: 'token',
        photoUrl: null
      });

      let result = await authService.authWithSocialProviderToken({
        code: 'code',
        provider: 'github',
        context: { ip: '1.2.3.4', ua: 'agent' },
        redirectUrl: 'https://example.com/callback',
        device: { oid: 2n } as any,
        app
      });

      expect(result).toMatchObject({
        type: 'auth_intent',
        authIntent: {
          type: 'oauth',
          userOid: user.oid,
          userIdentityOid: 5n,
          verifiedAt: null
        }
      });
      expect(db.userIdentity.update).not.toHaveBeenCalled();
      expect(userService.linkToAccount).not.toHaveBeenCalled();
      expect(deviceService.checkIfUserIsLoggedIn).not.toHaveBeenCalled();
      expect(authBlockService.registerBlock).toHaveBeenCalledWith({
        email: 'victim@example.com',
        context: { ip: '1.2.3.4', ua: 'agent' }
      });
      expect(db.authIntentStep.create).toHaveBeenCalledWith({
        data: expect.objectContaining({
          authIntentOid: 6n,
          type: 'email_code',
          email: 'victim@example.com'
        })
      });
      expect(sendAuthCodeEmail.send).toHaveBeenCalledWith({
        to: ['victim@example.com'],
        data: { code: expect.any(String) }
      });
    }
  );

  it('links the provider identity when the verified OAuth intent is completed', async () => {
    let authIntent = {
      oid: 6n,
      type: 'oauth',
      userOid: user.oid,
      userIdentityOid: 5n,
      deviceOid: 2n,
      accountOid: null,
      verifiedAt: new Date(),
      captchaVerifiedAt: new Date(),
      consumedAt: null,
      redirectUrl: 'https://example.com/callback',
      ip: '1.2.3.4',
      ua: 'agent',
      createdAt: new Date()
    } as any;
    db.user.findUnique.mockResolvedValue(user);
    db.authDevice.findUnique.mockResolvedValue({ oid: 2n });
    db.userIdentity.findUnique.mockResolvedValue({
      oid: 5n,
      userOid: null,
      provider: { name: 'Github' }
    });
    db.userIdentity.updateMany.mockResolvedValue({ count: 1 });
    let createAuthAttempt = vi
      .spyOn(authService, 'createAuthAttempt')
      .mockResolvedValue({ id: 'attempt_1' } as any);

    await expect(authService.completeAuthIntent({ authIntent, app })).resolves.toEqual({
      id: 'attempt_1'
    });

    expect(db.userIdentity.updateMany).toHaveBeenCalledWith({
      where: { oid: 5n, userOid: null },
      data: { userOid: user.oid }
    });
    expect(markAresUserChanged).toHaveBeenCalledWith({ userId: user.id, db });
    expect(createAuthAttempt).toHaveBeenCalledWith(
      expect.objectContaining({ user, authIntent, loginMethod: 'oauth' })
    );
  });
});

import { Paginator } from '@lowerdeck/pagination';
import { v } from '@lowerdeck/validation';
import { providerSpecificationChangeNotificationService } from '@metorial-subspace/module-catalog';
import { Controller } from '@metorial/rest';
import { dateFilterValidator } from '../../../lib/dateFilter';
import { normalizeArrayParam } from '../../../lib/normalizeArrayParam';
import { checkAccess } from '../../../middleware/checkAccess';
import { instanceGroup, instancePath } from '../../../middleware/instanceGroup';
import { providerSpecificationChangeNotificationPresenter } from '@metorial/presenters';
import { getRequiredParam, notificationTargetValidator, stringOrArray } from './_shared';

let providerSpecificationChangeNotificationGroup = instanceGroup.use(async ctx => {
  let notification =
    await providerSpecificationChangeNotificationService.getProviderSpecificationChangeNotificationById(
      {
        instance: ctx.instance,
        notificationId: getRequiredParam(ctx.params, 'notificationId')
      }
    );

  return { notification };
});

export let providerSpecificationChangeNotificationController = Controller.create(
  {
    name: 'Provider Specification Change Notifications',
    description:
      'Provider specification change notifications describe provider schema changes.'
  },
  {
    list: instanceGroup
      .get(
        instancePath(
          'provider-specification-change-notifications',
          'providerSpecificationChangeNotifications.list'
        ),
        {
          name: 'List provider specification change notifications',
          description:
            'Returns a paginated list of provider specification change notifications for this instance.'
        }
      )
      .use(checkAccess({ possibleScopes: ['instance.provider.specification:read'] }))
      .outputList(providerSpecificationChangeNotificationPresenter)
      .query(
        'default',
        Paginator.validate(
          v.object({
            id: v.optional(stringOrArray()),
            target: v.optional(
              v.union([notificationTargetValidator, v.array(notificationTargetValidator)])
            ),
            provider_id: v.optional(stringOrArray()),
            provider_version_id: v.optional(stringOrArray()),
            provider_specification_id: v.optional(stringOrArray()),
            created_at: dateFilterValidator('provider specification change notification time')
          })
        )
      )
      .do(async ctx => {
        let paginator =
          await providerSpecificationChangeNotificationService.listProviderSpecificationChangeNotifications(
            {
              instance: ctx.instance,
              ids: normalizeArrayParam(ctx.query.id),
              targets: normalizeArrayParam(ctx.query.target),
              providerIds: normalizeArrayParam(ctx.query.provider_id),
              providerVersionIds: normalizeArrayParam(ctx.query.provider_version_id),
              providerSpecificationIds: normalizeArrayParam(
                ctx.query.provider_specification_id
              ),
              createdAt: ctx.query.created_at
            }
          );

        return Paginator.present(await paginator.run(ctx.query), notification =>
          providerSpecificationChangeNotificationPresenter.present({ notification })
        );
      }),

    get: providerSpecificationChangeNotificationGroup
      .get(
        instancePath(
          'provider-specification-change-notifications/:notificationId',
          'providerSpecificationChangeNotifications.get'
        ),
        {
          name: 'Get provider specification change notification',
          description: 'Retrieves a provider specification change notification by ID.'
        }
      )
      .use(checkAccess({ possibleScopes: ['instance.provider.specification:read'] }))
      .output(providerSpecificationChangeNotificationPresenter)
      .do(async ctx =>
        providerSpecificationChangeNotificationPresenter.present({
          notification: ctx.notification
        })
      )
  }
);

