import type {
  Provider,
  ProviderAuthConfig,
  ProviderAuthCredentials,
  ProviderAuthMethod,
  ProviderDeployment,
  ProviderOAuthSetup,
  ProviderSpecification
} from '@metorial-subspace/db';
import { env } from '../../env';
import {
  setupSessionAuthConfigPresenter,
  setupSessionAuthCredentialsPresenter,
  setupSessionAuthMethodPresenter,
  setupSessionDeploymentPreviewPresenter
} from './setupSession';

export let setupSessionOAuthSetupPresenter = (
  providerOAuthSetup: ProviderOAuthSetup & {
    provider: Provider;
    deployment: ProviderDeployment | null;
    authCredentials: ProviderAuthCredentials | null;
    authMethod: ProviderAuthMethod & {
      specification: Omit<ProviderSpecification, 'value'>;
    };
    authConfig:
      | (ProviderAuthConfig & {
          deployment: ProviderDeployment | null;
        })
      | null;
  }
) => {
  let status =
    (providerOAuthSetup.status === 'opened' || providerOAuthSetup.status === 'unused') &&
    providerOAuthSetup.expiresAt <= new Date()
      ? ('expired' as const)
      : providerOAuthSetup.status;

  return {
    object: 'provider.oauth_setup',

    id: providerOAuthSetup.id,
    status,

    isEphemeral: providerOAuthSetup.isEphemeral,

    providerId: providerOAuthSetup.provider.id,

    name: providerOAuthSetup.name,
    description: providerOAuthSetup.description,
    metadata: providerOAuthSetup.metadata,
    toolFilter: providerOAuthSetup.toolFilter,

    redirectUrl: providerOAuthSetup.redirectUrl,
    errorCode: providerOAuthSetup.errorCode,
    errorMessage: providerOAuthSetup.errorMessage,

    url:
      status !== 'expired' && status !== 'completed'
        ? `${env.service.INTEGRATIONS_API_URL}/oauth-setup/${providerOAuthSetup.id}?client_secret=${providerOAuthSetup.clientSecret}`
        : null,

    authConfig: providerOAuthSetup.authConfig
      ? setupSessionAuthConfigPresenter({
          ...providerOAuthSetup.authConfig,
          provider: providerOAuthSetup.provider,
          authCredentials: providerOAuthSetup.authCredentials,
          authMethod: providerOAuthSetup.authMethod
        })
      : null,

    credentials: providerOAuthSetup.authCredentials
      ? setupSessionAuthCredentialsPresenter({
          ...providerOAuthSetup.authCredentials,
          provider: providerOAuthSetup.provider
        })
      : null,

    authMethod: setupSessionAuthMethodPresenter({
      ...providerOAuthSetup.authMethod,
      provider: providerOAuthSetup.provider
    }),

    deployment: providerOAuthSetup.deployment
      ? setupSessionDeploymentPreviewPresenter({
          ...providerOAuthSetup.deployment,
          provider: providerOAuthSetup.provider
        })
      : null,

    createdAt: providerOAuthSetup.createdAt,
    updatedAt: providerOAuthSetup.updatedAt,
    expiresAt: providerOAuthSetup.expiresAt
  };
};

import { Paginator } from '@lowerdeck/pagination';
import { v } from '@lowerdeck/validation';
import { slateInstanceOAuthSetupPresenter } from '../../presenters';
import { slateInstanceOAuthSetupLogsPresenter } from '../../presenters/slateOAuthSetupLogs';
import {
  slateInstanceConfigurationService,
  slateOAuthCredentialsService,
  slateOAuthSetupService,
  slateService,
  slateVersionService
} from '../../services';
import { app } from './_app';
import { tenantApp } from './tenant';

export let slateOAuthSetupApp = tenantApp.use(async ctx => {
  let slateOAuthSetupId = ctx.body.slateOAuthSetupId;
  if (!slateOAuthSetupId) throw new Error('Slate OAuthSetup ID is required');

  let slateOAuthSetup = await slateOAuthSetupService.getSlateInstanceOAuthSetupById({
    id: slateOAuthSetupId,
    tenant: ctx.tenant
  });

  return { slateOAuthSetup };
});

export let slateOAuthSetupSyncApp = app.use(async ctx => {
  let slateOAuthSetupId = ctx.body.slateOAuthSetupId;
  if (!slateOAuthSetupId) throw new Error('Slate OAuthSetup ID is required');

  let slateOAuthSetup =
    await slateOAuthSetupService.DANGEROUSLY_getSlateInstanceOAuthSetupById({
      id: slateOAuthSetupId
    });

  return { slateOAuthSetup };
});

export let slateOAuthSetupController = app.controller({
  list: tenantApp
    .handler()
    .input(
      Paginator.validate(
        v.object({
          tenantId: v.string(),
          slateIds: v.optional(v.array(v.string()))
        })
      )
    )
    .do(async ctx => {
      let paginator = await slateOAuthSetupService.listSlateInstanceOAuthSetups({
        tenant: ctx.tenant,
        slateIds: ctx.input.slateIds
      });

      let list = await paginator.run(ctx.input);

      return Paginator.presentLight(list, slateInstanceOAuthSetupPresenter);
    }),

  listIncomplete: app
    .handler()
    .input(
      Paginator.validate(
        v.object({
          slateOAuthSetupIds: v.optional(v.array(v.string()))
        })
      )
    )
    .do(async ctx => {
      let paginator = await slateOAuthSetupService.listIncompleteSlateInstanceOAuthSetups({
        slateOAuthSetupIds: ctx.input.slateOAuthSetupIds
      });

      let list = await paginator.run(ctx.input);

      return Paginator.presentLight(list, slateInstanceOAuthSetupPresenter);
    }),

  create: tenantApp
    .handler()
    .input(
      Paginator.validate(
        v.object({
          tenantId: v.string(),
          slateId: v.string(),
          slateOAuthCredentialsId: v.string(),
          slateVersionId: v.optional(v.string()),
          slateInstanceConfigurationId: v.optional(v.string()),
          authMethodId: v.optional(v.string()),
          redirectUrl: v.string(),
          input: v.record(v.any()),
          callbackUrlOverride: v.optional(v.string())
        })
      )
    )
    .do(async ctx => {
      let slate = await slateService.getSlateById({
        id: ctx.input.slateId
      });
      let oauthCredentials = await slateOAuthCredentialsService.getSlateOAuthCredentialsById({
        id: ctx.input.slateOAuthCredentialsId,
        tenant: ctx.tenant
      });
      let slateVersion = ctx.input.slateVersionId
        ? await slateVersionService.getSlateVersionById({
            id: ctx.input.slateVersionId,
            slate
          })
        : undefined;
      let instanceConfiguration = ctx.input.slateInstanceConfigurationId
        ? await slateInstanceConfigurationService.getSlateInstanceConfigurationById({
            tenant: ctx.tenant,
            slateInstanceConfigurationId: ctx.input.slateInstanceConfigurationId
          })
        : undefined;

      let res = await slateOAuthSetupService.createSlateInstanceOAuthSetup({
        tenant: ctx.tenant,

        input: {
          slate,
          slateVersion,
          oauthCredentials,
          instanceConfiguration,

          redirectUrl: ctx.input.redirectUrl,
          authMethodId: ctx.input.authMethodId,

          input: ctx.input.input,

          callbackUrlOverride: ctx.input.callbackUrlOverride
        }
      });

      return slateInstanceOAuthSetupPresenter(res);
    }),

  get: slateOAuthSetupApp
    .handler()
    .input(
      v.object({
        tenantId: v.string(),
        slateOAuthSetupId: v.string()
      })
    )
    .do(async ctx => slateInstanceOAuthSetupPresenter(ctx.slateOAuthSetup)),

  getLogs: slateOAuthSetupApp
    .handler()
    .input(
      v.object({
        tenantId: v.string(),
        slateOAuthSetupId: v.string()
      })
    )
    .do(async ctx => {
      let logs = await slateOAuthSetupService.getSlateInstanceOAuthSetupLogs({
        setup: ctx.slateOAuthSetup
      });

      return await slateInstanceOAuthSetupLogsPresenter(logs);
    }),

  getLogsSync: slateOAuthSetupSyncApp
    .handler()
    .input(
      v.object({
        slateOAuthSetupId: v.string()
      })
    )
    .do(async ctx => {
      let logs = await slateOAuthSetupService.getSlateInstanceOAuthSetupLogs({
        setup: ctx.slateOAuthSetup
      });

      return await slateInstanceOAuthSetupLogsPresenter(logs);
    }),

  getMany: tenantApp
    .handler()
    .input(
      v.object({
        tenantId: v.string(),
        slateOAuthSetupIds: v.array(v.string())
      })
    )
    .do(async ctx => {
      let slateOAuthSetups = await slateOAuthSetupService.getManySlateInstanceOAuthSetupsByIds(
        {
          ids: ctx.input.slateOAuthSetupIds,
          tenant: ctx.tenant
        }
      );

      return slateOAuthSetups.map(slateInstanceOAuthSetupPresenter);
    })
});

import { badRequestError, ServiceError } from '@lowerdeck/error';
import { Paginator } from '@lowerdeck/pagination';
import { v } from '@lowerdeck/validation';
import { oauthAuthorizationInstallationService } from '@metorial/module-machine-access';
import { Controller } from '@metorial/rest';
import { normalizeArrayParam } from '../../../lib/normalizeArrayParam';
import { checkAccess } from '../../../middleware/checkAccess';
import {
  organizationGroup,
  organizationManagementPath
} from '../../../middleware/organizationGroup';
import { oauthInstallationPresenter } from '@metorial/presenters';

let oauthInstallationManagementGroup = organizationGroup.use(async ctx => {
  if (!ctx.params.oauthInstallationId) {
    throw new ServiceError(
      badRequestError({
        message: 'oauthInstallationId is required'
      })
    );
  }

  let oauthInstallation = await oauthAuthorizationInstallationService.getOAuthInstallationById(
    {
      organization: ctx.organization,
      oauthInstallationId: ctx.params.oauthInstallationId
    }
  );

  return { oauthInstallation };
});

export let oauthInstallationManagementController = Controller.create(
  {
    name: 'OAuth Installation',
    description: 'Inspect and revoke OAuth app installations for an organization'
  },
  {
    list: organizationGroup
      .get(organizationManagementPath('oauth/installations', 'oauth.installations.list'), {
        name: 'List organization OAuth installations',
        description: 'Returns a paginated list of OAuth installations for the organization.'
      })
      .use(checkAccess({ possibleScopes: ['organization.oauth_installation:read'] }))
      .outputList(oauthInstallationPresenter)
      .query(
        'default',
        Paginator.validate(
          v.object({
            status: v.optional(
              v.union([
                v.enumOf(['active', 'revoked']),
                v.array(v.enumOf(['active', 'revoked']))
              ]),
              { description: 'Filter by installation status' }
            ),
            app_id: v.optional(v.union([v.string(), v.array(v.string())]), {
              description: 'Filter by OAuth application ID(s)'
            })
          })
        )
      )
      .do(async ctx => {
        let paginator = await oauthAuthorizationInstallationService.listOAuthInstallations({
          organization: ctx.organization,
          statuses: normalizeArrayParam(ctx.query.status),
          oauthApplicationIds: normalizeArrayParam(ctx.query.app_id)
        });

        let list = await paginator.run(ctx.query);

        return Paginator.present(list, oauthInstallation =>
          oauthInstallationPresenter.present({ oauthInstallation })
        );
      }),

    get: oauthInstallationManagementGroup
      .get(
        organizationManagementPath(
          'oauth/installations/:oauthInstallationId',
          'oauth.installations.get'
        ),
        {
          name: 'Get organization OAuth installation',
          description: 'Retrieves a specific OAuth installation for the organization.'
        }
      )
      .use(checkAccess({ possibleScopes: ['organization.oauth_installation:read'] }))
      .output(oauthInstallationPresenter)
      .do(async ctx => {
        return oauthInstallationPresenter.present({
          oauthInstallation: ctx.oauthInstallation
        });
      }),

    revoke: oauthInstallationManagementGroup
      .post(
        organizationManagementPath(
          'oauth/installations/:oauthInstallationId/revoke',
          'oauth.installations.revoke'
        ),
        {
          name: 'Revoke organization OAuth installation',
          description: 'Revokes a specific OAuth installation for the organization.'
        }
      )
      .use(checkAccess({ possibleScopes: ['organization.oauth_installation:write'] }))
      .output(oauthInstallationPresenter)
      .do(async ctx => {
        let oauthInstallation =
          await oauthAuthorizationInstallationService.revokeOAuthInstallation({
            oauthInstallation: ctx.oauthInstallation,
            auditScope: ctx.auditScope
          });

        return oauthInstallationPresenter.present({ oauthInstallation });
      })
  }
);

import { badRequestError, ServiceError } from '@lowerdeck/error';
import { Paginator } from '@lowerdeck/pagination';
import { v } from '@lowerdeck/validation';
import {
  providerAuthCredentialsService,
  providerSetupSessionService
} from '@metorial-subspace/module-auth';
import { providerService } from '@metorial-subspace/module-catalog';
import { providerDeploymentService } from '@metorial-subspace/module-deployment';
import { identityService } from '@metorial-subspace/module-identity';
import { Controller } from '@metorial/rest';
import { dateFilterValidator } from '../../../lib/dateFilter';
import { normalizeArrayParam } from '../../../lib/normalizeArrayParam';
import { checkAccess } from '../../../middleware/checkAccess';
import { instanceGroup, instancePath } from '../../../middleware/instanceGroup';
import { providerSetupSessionPresenter } from '@metorial/presenters';

let providerSetupSessionConfigurationValidator = v.optional(
  v.object({
    provider_search: v.optional(
      v.object({
        groups: v.optional(v.array(v.object({ group_id: v.string() }))),
        collections: v.optional(v.array(v.object({ collection_id: v.string() }))),
        categories: v.optional(v.array(v.object({ category_id: v.string() })))
      })
    ),
    tool_filters: v.optional(
      v.object({
        enabled: v.optional(v.boolean())
      })
    ),
    ui: v.optional(
      v.object({
        layout: v.optional(v.enumOf(['box', 'side', 'light']))
      })
    )
  })
);

let providerSetupSessionGroup = instanceGroup.use(async ctx => {
  if (!ctx.params.providerSetupSessionId) {
    throw new ServiceError(
      badRequestError({
        message: 'providerSetupSessionId is required',
        description: 'The providerSetupSessionId path parameter is required.'
      })
    );
  }

  let setupSession = await providerSetupSessionService.getProviderSetupSessionById({
    instance: ctx.instance,
    providerSetupSessionId: ctx.params.providerSetupSessionId
  });

  return { setupSession };
});

export let providerSetupSessionController = Controller.create(
  {
    name: 'Provider Setup Sessions',
    description:
      "A setup session tracks an in-progress OAuth flow, storing state during the redirect. On success, it creates an auth config with the user's access token."
  },
  {
    list: instanceGroup
      .get(instancePath('provider-setup-sessions', 'providerDeployments.setupSessions.list'), {
        name: 'List provider setup sessions',
        description: 'Returns a paginated list of provider setup sessions.'
      })
      .use(checkAccess({ possibleScopes: ['instance.provider.auth:read'] }))
      .outputList(providerSetupSessionPresenter)
      .query(
        'default',
        Paginator.validate(
          v.object({
            id: v.optional(v.union([v.string(), v.array(v.string())]), {
              description: 'Filter by setup session ID(s)'
            }),
            provider_id: v.optional(v.union([v.string(), v.array(v.string())]), {
              description: 'Filter by provider ID(s)'
            }),
            provider_deployment_id: v.optional(v.union([v.string(), v.array(v.string())]), {
              description: 'Filter by provider deployment ID(s)'
            }),
            provider_auth_method_id: v.optional(v.union([v.string(), v.array(v.string())]), {
              description: 'Filter by auth method ID(s)'
            }),
            provider_auth_config_id: v.optional(v.union([v.string(), v.array(v.string())]), {
              description: 'Filter by provider auth config ID(s)'
            }),
            provider_auth_credentials_id: v.optional(
              v.union([v.string(), v.array(v.string())]),
              { description: 'Filter by provider auth credentials ID(s)' }
            ),
            status: v.optional(
              v.union([
                v.enumOf(['archived', 'failed', 'completed', 'expired', 'pending']),
                v.array(v.enumOf(['archived', 'failed', 'completed', 'expired', 'pending']))
              ]),
              {
                description:
                  'Filter by session status (archived, failed, completed, expired, pending)'
              }
            ),
            created_at: dateFilterValidator('provider setup session creation time'),
            updated_at: dateFilterValidator('provider setup session last update time')
          })
        )
      )
      .do(async ctx => {
        let paginator = await providerSetupSessionService.listProviderSetupSessions({
          instance: ctx.instance,
          allowDeleted: false,

          ids: normalizeArrayParam(ctx.query.id),
          providerIds: normalizeArrayParam(ctx.query.provider_id),
          providerDeploymentIds: normalizeArrayParam(ctx.query.provider_deployment_id),
          providerAuthMethodIds: normalizeArrayParam(ctx.query.provider_auth_method_id),
          providerAuthConfigIds: normalizeArrayParam(ctx.query.provider_auth_config_id),
          providerAuthCredentialsIds: normalizeArrayParam(
            ctx.query.provider_auth_credentials_id
          ),
          status: normalizeArrayParam(ctx.query.status),
          createdAt: ctx.query.created_at,
          updatedAt: ctx.query.updated_at
        });

        let list = await paginator.run(ctx.query);

        return Paginator.present(list, setupSession =>
          providerSetupSessionPresenter.present({
            setupSession
          })
        );
      }),

    get: providerSetupSessionGroup
      .get(
        instancePath(
          'provider-setup-sessions/:providerSetupSessionId',
          'providerDeployments.setupSessions.get'
        ),
        {
          name: 'Get provider setup session',
          description: 'Retrieves a specific provider setup session by ID.'
        }
      )
      .use(checkAccess({ possibleScopes: ['instance.provider.auth:read'] }))
      .output(providerSetupSessionPresenter)
      .do(async ctx => {
        return providerSetupSessionPresenter.present({ setupSession: ctx.setupSession });
      }),

    create: instanceGroup
      .post(
        instancePath('provider-setup-sessions', 'providerDeployments.setupSessions.create'),
        {
          name: 'Create provider setup session',
          description: 'Creates a new provider setup session for OAuth authentication.'
        }
      )
      .use(checkAccess({ possibleScopes: ['instance.provider.auth:write'] }))
      .body(
        'default',
        v.object({
          provider_id: v.optional(
            v.string({
              examples: ['pro_5gHjKlMnPqRsTuVw'],
              description: 'The provider ID'
            })
          ),
          provider_deployment_id: v.optional(
            v.string({
              examples: ['pdp_4dEfGhJkLmNpQrSt'],
              description: 'Optional provider deployment ID'
            })
          ),
          name: v.optional(v.string({ examples: ['GitHub OAuth Setup'] })),
          description: v.optional(v.string({ examples: ['Connect your GitHub account'] })),
          metadata: v.optional(
            v.record(v.any(), {
              examples: [{ redirect_uri: 'https://app.example.com/callback' }]
            }),
            { description: 'Custom key-value pairs for storing additional information' }
          ),
          provider_auth_method_id: v.optional(
            v.string({
              examples: ['pam_2mNpQrStUvWxYzAb'],
              description: 'The authentication method to use (e.g., OAuth flow)'
            })
          ),
          provider_auth_credentials_id: v.optional(
            v.string({
              examples: ['pac_3nOpRsTuVwXyZaBc'],
              description: 'Optional OAuth app credentials to use instead of defaults'
            })
          ),
          identity_id: v.optional(
            v.string({
              examples: ['idn_3nOpRsTuVwXyZaBc'],
              description: 'Optional identity to link this setup session to'
            })
          ),
          consumer_id: v.optional(
            v.string({
              examples: ['con_1a2b3c4d5e6f7g8h'],
              description: 'Optional consumer to link this setup session to'
            })
          ),
          redirect_url: v.optional(
            v.string({ examples: ['https://app.example.com/oauth/callback'] })
          ),
          type: v.optional(
            v.enumOf(['auth_only', 'config_only', 'auth_and_config', 'auto'], {
              description:
                'The type of setup session, determining the flow and outcome of the session'
            })
          ),
          configuration: providerSetupSessionConfigurationValidator
        })
      )
      .output(providerSetupSessionPresenter)
      .do(async ctx => {
        let provider = ctx.body.provider_id
          ? await providerService.getProviderById({
              instance: ctx.instance,
              providerId: ctx.body.provider_id
            })
          : undefined;
        let providerDeployment = ctx.body.provider_deployment_id
          ? await providerDeploymentService.getProviderDeploymentById({
              instance: ctx.instance,
              providerDeploymentId: ctx.body.provider_deployment_id
            })
          : undefined;
        let credentials = ctx.body.provider_auth_credentials_id
          ? await providerAuthCredentialsService.getProviderAuthCredentialsById({
              instance: ctx.instance,
              providerAuthCredentialsId: ctx.body.provider_auth_credentials_id
            })
          : undefined;
        let identity = ctx.body.identity_id
          ? await identityService.getIdentityById({
              instance: ctx.instance,
              identityId: ctx.body.identity_id
            })
          : undefined;

        let setupSession = await providerSetupSessionService.createProviderSetupSession({
          instance: ctx.instance,
          auditScope: ctx.auditScope,
          provider,
          providerDeployment,
          credentials,
          identity,
          consumerId: ctx.body.consumer_id,
          import: {
            ip: ctx.context.ip,
            ua: ctx.context.ua ?? ''
          },
          input: {
            authMethodId: ctx.body.provider_auth_method_id,
            configuration: (ctx.body.configuration
              ? {
                  providerSearch: ctx.body.configuration.provider_search
                    ? {
                        groups: ctx.body.configuration.provider_search.groups?.map(group => ({
                          groupId: group.group_id
                        })),
                        collections: ctx.body.configuration.provider_search.collections?.map(
                          collection => ({
                            collectionId: collection.collection_id
                          })
                        ),
                        categories: ctx.body.configuration.provider_search.categories?.map(
                          category => ({
                            categoryId: category.category_id
                          })
                        )
                      }
                    : undefined,
                  toolFilters: ctx.body.configuration.tool_filters
                    ? { enabled: ctx.body.configuration.tool_filters.enabled }
                    : undefined,
                  ui: ctx.body.configuration.ui
                    ? {
                        layout: ctx.body.configuration.ui.layout
                      }
                    : undefined
                }
              : undefined) as any,
            name: ctx.body.name ?? 'Setup Session',
            description: ctx.body.description,
            uiMode: 'metorial_elements',
            type:
              ctx.body.type ??
              (ctx.apiVersion === 'mt_2025_01_01_dashboard' ? 'auth_only' : 'auto'),
            redirectUrl: ctx.body.redirect_url,
            metadata: ctx.body.metadata
          }
        });

        return providerSetupSessionPresenter.present({
          setupSession
        });
      }),

    update: providerSetupSessionGroup
      .patch(
        instancePath(
          'provider-setup-sessions/:providerSetupSessionId',
          'providerDeployments.setupSessions.update'
        ),
        {
          name: 'Update provider setup session',
          description: 'Updates a specific provider setup session.'
        }
      )
      .use(checkAccess({ possibleScopes: ['instance.provider.auth:write'] }))
      .body(
        'default',
        v.object({
          name: v.optional(v.string({ examples: ['Updated Setup Session'] })),
          description: v.optional(
            v.string({ examples: ['Updated setup session description'] })
          ),
          metadata: v.optional(
            v.record(v.any(), {
              examples: [{ redirect_uri: 'https://app.example.com/new-callback' }]
            }),
            { description: 'Custom key-value pairs for storing additional information' }
          ),
          identity_id: v.optional(
            v.string({
              examples: ['idn_3nOpRsTuVwXyZaBc'],
              description: 'Optional identity to link this setup session to'
            })
          )
        })
      )
      .output(providerSetupSessionPresenter)
      .do(async ctx => {
        let identity = ctx.body.identity_id
          ? await identityService.getIdentityById({
              instance: ctx.instance,
              identityId: ctx.body.identity_id
            })
          : undefined;
        let setupSession = await providerSetupSessionService.updateProviderSetupSession({
          instance: ctx.instance,
          auditScope: ctx.auditScope,
          providerSetupSession: ctx.setupSession,
          input: {
            name: ctx.body.name,
            description: ctx.body.description,
            metadata: ctx.body.metadata,
            identity
          }
        });

        return providerSetupSessionPresenter.present({
          setupSession
        });
      }),

    delete: providerSetupSessionGroup
      .delete(
        instancePath(
