    await Promise.all([
      serverOAuthSetupService.consumeServerOAuthSetup({ serverOAuthSetupId: setup.id }),
      serverOAuthSetupService.consumeServerOAuthSetup({ serverOAuthSetupId: setup.id })
    ]);

