export const SlateOAuthSetupFixtures = (db: PrismaClient) => {
  const defaultSetup = async (data: {
    slateOid: bigint;
    tenantOid: bigint;
    slateVersionOid: bigint;
    authMethodOid: bigint;
    oauthCredentialsOid: bigint;
    secretOid: bigint;
    status?: SlateInstanceOAuthSetupStatus;
    overrides?: Partial<SlateInstanceOAuthSetup>;
  }): Promise<SlateInstanceOAuthSetup> => {
    const { oid, id } = getId('slateInstanceOAuthSetup');

    const factory = defineFactory<SlateInstanceOAuthSetup>(
      {
        oid,
        id,
        status: data.status ?? SlateInstanceOAuthSetupStatus.unused,
        redirectUrl: 'https://example.com/callback',
        slateOid: data.slateOid,
        tenantOid: data.tenantOid,
        slateVersionOid: data.slateVersionOid,
        authMethodOid: data.authMethodOid,
        oauthCredentialsOid: data.oauthCredentialsOid,
        secretOid: data.secretOid,
        ...data.overrides
      } as SlateInstanceOAuthSetup,
      {
        persist: value => db.slateInstanceOAuthSetup.create({ data: value })
      }
    );

    return factory.create(data.overrides ?? {});
  };

  const withSecret = async (data: {
    tenantOid: bigint;
    slateOid: bigint;
    slateVersionOid: bigint;
    authMethodOid: bigint;
    oauthCredentialsOid: bigint;
  }): Promise<SlateInstanceOAuthSetup> => {
    const secretFixtures = SecretFixtures(db);
    const secret = await secretFixtures.default({
      tenantOid: data.tenantOid,
      type: SecretType.slate_oauth_setup
    });
    return defaultSetup({
      slateOid: data.slateOid,
      tenantOid: data.tenantOid,
      slateVersionOid: data.slateVersionOid,
      authMethodOid: data.authMethodOid,
      oauthCredentialsOid: data.oauthCredentialsOid,
      secretOid: secret.oid
    });
  };

  const complete = async (data?: {
    slateIdentifier?: string;
    slateStatus?: SlateStatus;
    status?: SlateInstanceOAuthSetupStatus;
    setupOverrides?: Partial<SlateInstanceOAuthSetup>;
  }): Promise<{
    setup: SlateInstanceOAuthSetup;
    credentials: SlateOAuthCredentials;
    authMethod: SlateAuthMethod;
    slate: Slate & { currentVersion: SlateVersion };
    tenant: Tenant;
    secret: Secret;
  }> => {
    const tenantFixtures = TenantFixtures(db);
    const tenant = await tenantFixtures.default();

    const slateFixtures = SlateFixtures(db);
    const slate = await slateFixtures.complete({
      slateIdentifier: data?.slateIdentifier,
      slateStatus: data?.slateStatus ?? SlateStatus.active
    });

    const authMethodFixtures = SlateAuthMethodFixtures(db);
    const authMethod = await authMethodFixtures.default({
      slateOid: slate.oid,
      specificationOid: slate.currentVersion.specification.oid
    });

    const secretFixtures = SecretFixtures(db);
    const credentialsSecret = await secretFixtures.default({
      tenantOid: tenant.oid,
      type: SecretType.slate_oauth_credentials
    });

    const credentialsFixtures = SlateOAuthCredentialsFixtures(db);
    const credentials = await credentialsFixtures.default({
      slateOid: slate.oid,
      tenantOid: tenant.oid,
      secretOid: credentialsSecret.oid
    });

    const setupSecret = await secretFixtures.default({
      tenantOid: tenant.oid,
      type: SecretType.slate_oauth_setup
    });

    const setup = await defaultSetup({
      slateOid: slate.oid,
      tenantOid: tenant.oid,
      slateVersionOid: slate.currentVersion.oid,
      authMethodOid: authMethod.oid,
      oauthCredentialsOid: credentials.oid,
      secretOid: setupSecret.oid,
      status: data?.status,
      overrides: data?.setupOverrides
    });

    return { setup, credentials, authMethod, slate, tenant, secret: setupSecret };
  };

  return {
    default: defaultSetup,
    withSecret,
    complete
  };
};

import { expect, test } from 'bun:test';
import {
  existsSync,
  mkdtempSync,
  mkdirSync,
  rmSync,
  writeFileSync,
  readFileSync,
  symlinkSync
} from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { installKey } from './install-key';

let runtime = { bun: '1.4.2', node: 'v22.22.0', os: 'linux', arch: 'x64' };

test('install identity follows dependencies, lifecycle sources and runtime without following ordinary test edits', () => {
  let workspace = mkdtempSync(join(tmpdir(), 'install-key-'));
  let files = [
    'package.json',
    'bun.lock',
    'bunfig.toml',
    'src/unit.test.ts',
    'packages/native/postinstall.ts'
  ];
  try {
    for (let path of files) {
      mkdirSync(join(workspace, path, '..'), { recursive: true });
      writeFileSync(join(workspace, path), 'original');
    }
    let options = { workspace, files, lifecycleDirectories: ['packages/native'], runtime };
    let before = installKey(options);
    writeFileSync(join(workspace, 'src/unit.test.ts'), 'changed');
    expect(installKey(options)).toBe(before);
    for (let path of [
      'package.json',
      'bun.lock',
      'bunfig.toml',
      'packages/native/postinstall.ts'
    ]) {
      writeFileSync(join(workspace, path), 'changed');
      expect(installKey(options)).not.toBe(before);
      writeFileSync(join(workspace, path), 'original');
    }
    for (let patch of [
      { bun: '1.4.3' },
      { node: 'v24' },
      { os: 'darwin' },
      { arch: 'arm64' }
    ]) {
      expect(installKey({ ...options, runtime: { ...runtime, ...patch } })).not.toBe(before);
    }
  } finally {
    rmSync(workspace, { recursive: true, force: true });
  }
});

test('captures and restores nested hoisted installs and workspace links', () => {
  let temporary = mkdtempSync(join(tmpdir(), 'install-restore-'));
  let workspace = join(temporary, 'test-workspace');
  try {
    for (let path of [
      'node_modules/normal/index.js',
      'packages/a/node_modules/nested/index.js',
      'packages/a/package.json'
    ]) {
      mkdirSync(join(workspace, path, '..'), { recursive: true });
      writeFileSync(join(workspace, path), path);
    }
    writeFileSync(
      join(workspace, '.test-install-paths.json'),
      JSON.stringify(['node_modules', 'packages/a/node_modules'])
    );
    let execute = (command: string) => {
      let result = Bun.spawnSync(['bun', join(import.meta.dir, 'workspace.ts'), command], {
        env: { ...process.env, RUNNER_TEMP: temporary },
        stdout: 'pipe',
        stderr: 'pipe'
      });
      expect(result.exitCode).toBe(0);
    };
    symlinkSync('../packages/a', join(workspace, 'node_modules/workspace-a'));
    execute('capture');
    rmSync(join(workspace, 'node_modules'), { recursive: true });
    rmSync(join(workspace, 'packages/a/node_modules'), { recursive: true });
    execute('restore');
    expect(existsSync(join(temporary, 'test-install/node_modules'))).toBe(false);
    expect(
      readFileSync(join(workspace, 'node_modules/workspace-a/package.json'), 'utf8')
    ).toBe('packages/a/package.json');
    expect(readFileSync(join(workspace, 'node_modules/normal/index.js'), 'utf8')).toBe(
      'node_modules/normal/index.js'
    );
    expect(
      readFileSync(join(workspace, 'packages/a/node_modules/nested/index.js'), 'utf8')
    ).toBe('packages/a/node_modules/nested/index.js');
  } finally {
    rmSync(temporary, { recursive: true, force: true });
  }
});

