import { providerSetupSessionService } from './providerSetupSession';

let makeParams = ({
  projectOid = 20n as bigint | null,
  instanceOid = 40n as bigint | null
} = {}) => ({
  tenant: { oid: 10n, projectOid } as any,
  environment: { oid: 30n, instanceOid } as any,
  input: {
    type: 'auto' as const,
    uiMode: 'metorial_elements' as const
  },
  import: { ip: '127.0.0.1', ua: 'test-agent' }
});

describe('createProviderSetupSessionInternal double writes', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mocks.providerSetupSessionCreate.mockResolvedValue({ oid: 100n, id: 'pss_1' });
    mocks.providerSetupSessionFindUniqueOrThrow.mockResolvedValue({ oid: 100n, id: 'pss_1' });
  });

  it('mirrors the tenant project and environment instance onto the setup session', async () => {
    await providerSetupSessionService.createProviderSetupSessionInternal(makeParams() as any);

    expect(mocks.providerSetupSessionCreate).toHaveBeenCalledTimes(1);
    expect(mocks.providerSetupSessionCreate.mock.calls[0]![0].data).toMatchObject({
      tenantOid: 10n,
      projectOid: 20n,
      environmentOid: 30n,
      instanceOid: 40n
    });
  });

  it('keeps the mirrored oids null while the tenant is not linked yet', async () => {
    await providerSetupSessionService.createProviderSetupSessionInternal(
      makeParams({ projectOid: null, instanceOid: null }) as any
    );

    expect(mocks.providerSetupSessionCreate.mock.calls[0]![0].data).toMatchObject({
      tenantOid: 10n,
      projectOid: null,
      environmentOid: 30n,
      instanceOid: null
    });
  });

  it("owns the session by the identity's actor when no owner is given", async () => {
    await providerSetupSessionService.createProviderSetupSessionInternal({
      ...makeParams(),
      identity: { oid: 50n, actorOid: 60n, tenantOid: 10n, status: 'active' }
    } as any);

    expect(mocks.providerSetupSessionCreate.mock.calls[0]![0].data).toMatchObject({
      identityOid: 50n,
      ownerActorOid: 60n
    });
  });

  it('prefers an explicit owner actor over the identity actor', async () => {
    await providerSetupSessionService.createProviderSetupSessionInternal({
      ...makeParams(),
      identity: { oid: 50n, actorOid: 60n, tenantOid: 10n, status: 'active' },
      ownerActorOid: 70n
    } as any);

    expect(mocks.providerSetupSessionCreate.mock.calls[0]![0].data).toMatchObject({
      ownerActorOid: 70n
    });
  });

  it('leaves the session unowned without an identity or owner', async () => {
    await providerSetupSessionService.createProviderSetupSessionInternal(makeParams() as any);

    expect(mocks.providerSetupSessionCreate.mock.calls[0]![0].data).toMatchObject({
      ownerActorOid: null
    });
  });
});

import { describe, expect, it } from 'vitest';
import { getEntryActions, isDownloadable } from './actions';

let actionsOf = (items: ReturnType<typeof getEntryActions>) =>
  items.map(item => ('action' in item ? item.action : '---'));

describe('getEntryActions', () => {
  it('offers the full set for a regular file', () => {
    expect(actionsOf(getEntryActions({ type: 'file' }))).toEqual([
      'open',
      'download',
      '---',
      'rename',
      'move',
      'delete'
    ]);
  });

  it('does not offer download for folders', () => {
    expect(actionsOf(getEntryActions({ type: 'directory' }))).toEqual([
      'open',
      '---',
      'rename',
      'move',
      'delete'
    ]);
  });

  it('removes every mutation when read-only', () => {
    expect(actionsOf(getEntryActions({ type: 'file' }, { readOnly: true }))).toEqual([
      'open',
      'download'
    ]);
  });

  it('only downloads files and links to files', () => {
    expect(isDownloadable({ type: 'file' })).toBe(true);
    expect(isDownloadable({ type: 'symlink', targetType: 'file' })).toBe(true);
    expect(isDownloadable({ type: 'symlink', targetType: 'directory' })).toBe(false);
    expect(isDownloadable({ type: 'other' })).toBe(false);
  });
});

import { Hono } from 'hono';
import { beforeEach, describe, expect, it, vi } from 'vitest';

let { isServiceGrantedForInstance } = vi.hoisted(() => ({
  isServiceGrantedForInstance: vi.fn()
}));

vi.mock('@metorial/module-outpost', () => ({
  outpostAccessService: { isServiceGrantedForInstance },
  outpostVerificationTokens: {},
  metorialOutpostResolver: {}
}));

import { createPortalOAuthServers } from '../src/oauth/skeleton';
import { assertOutpostOAuthRouteAccess, setOutpostAuth } from '../src/outpost';

let fakeAuth = () =>
  ({
    outpostId: 'otp_1',
    instanceId: 'oti_1',
    credentialId: 'otc_1',
    service: 'mcp_connection_proxy',
    grantedServices: ['mcp_connection_proxy'],
    requestId: 'oprq_1',
    timestamp: Math.floor(Date.now() / 1000),
    outpostChain: [],
    proxyContext: {}
  }) as any;

let buildServers = () =>
  createPortalOAuthServers({
    resolveRoute: async () => ({
      base: 'https://example.test',
      projectOid: 42n,
      instanceOid: 84n
    }),
    authorizeRoute: assertOutpostOAuthRouteAccess,
    metadata: async ({ route }, c) => c.json({ base: route.base }),
    portal: async ({ route }, c) => c.json({ base: route.base }),
    protectedResource: async ({ route }, c) => c.json({ base: route.base }),
    openIdConfiguration: async ({ route }, c) => c.json({ base: route.base }),
    register: async ({ route }, c) => c.json({ base: route.base }),
    authorize: async ({ route }, c) => c.json({ base: route.base }),
    token: async ({ route }, c) => c.json({ base: route.base }),
    registration: async ({ route }, c) => c.json({ base: route.base })
  });

describe('createOAuthRouteServers (via createPortalOAuthServers) instance gating', () => {
  beforeEach(() => {
    isServiceGrantedForInstance.mockReset();
  });

  it('lets a direct (non-outpost) request through untouched', async () => {
    let { metadataServer } = buildServers();

    let res = await metadataServer.request('http://test/portal_1');

    expect(res.status).toBe(200);
    expect(isServiceGrantedForInstance).not.toHaveBeenCalled();
  });

  // In production, `outpostConnectionAuthMiddleware` runs on the *parent* app before it
  // delegates into a `.route()`-mounted sub-app (see `connectApi`/`startMcpServer`) -- Hono
  // shares the same Context across that mount boundary, so `c.set`/`c.get` carry through. This
  // mounts the built server the same way to exercise that boundary faithfully.
  let mount = (sub: { fetch: typeof Hono.prototype.fetch }) =>
    new Hono()
      .use('*', async (c, next) => {
        setOutpostAuth(c, fakeAuth());
        return next();
      })
      .route('/', sub as any);

  it('lets an outpost-authenticated request through when the instance is granted', async () => {
    isServiceGrantedForInstance.mockResolvedValue(true);
    let { metadataServer } = buildServers();

    let res = await mount(metadataServer).request('http://test/portal_1');

    expect(res.status).toBe(200);
    expect(isServiceGrantedForInstance).toHaveBeenCalledWith({
      outpostId: 'otp_1',
      projectOid: 42n,
      instanceOid: 84n,
      service: 'mcp_connection_proxy'
    });
  });

  it('rejects an outpost-authenticated request when the instance is not granted', async () => {
    isServiceGrantedForInstance.mockResolvedValue(false);
    let { metadataServer } = buildServers();

    let res = await mount(metadataServer).request('http://test/portal_1');

    expect(res.status).toBe(403);
  });

  it('does not consult outpost access unless authorizeRoute is wired (global-router path)', async () => {
    isServiceGrantedForInstance.mockResolvedValue(false);
    let { metadataServer } = createPortalOAuthServers({
      resolveRoute: async () => ({
        base: 'https://example.test',
        host: 'region.example'
      }),
      metadata: async ({ route }, c) => c.json({ base: route.base }),
      portal: async ({ route }, c) => c.json({ base: route.base }),
      protectedResource: async ({ route }, c) => c.json({ base: route.base }),
      openIdConfiguration: async ({ route }, c) => c.json({ base: route.base }),
      register: async ({ route }, c) => c.json({ base: route.base }),
      authorize: async ({ route }, c) => c.json({ base: route.base }),
      token: async ({ route }, c) => c.json({ base: route.base }),
      registration: async ({ route }, c) => c.json({ base: route.base })
    });

    let res = await mount(metadataServer).request('http://test/portal_1');

    expect(res.status).toBe(200);
    expect(isServiceGrantedForInstance).not.toHaveBeenCalled();
  });

  it('also gates the registration lookup route, which resolves the route outside of withResolvedRoute', async () => {
    isServiceGrantedForInstance.mockResolvedValue(false);
    let { connectPortalServer } = buildServers();

    let res = await mount(connectPortalServer).request(
      'http://test/portal_1/oauth/register/reg_1'
    );

    expect(res.status).toBe(403);
  });
});

import { describe, expect, it, vi } from 'vitest';
import { resolveDocumentsLiveToken } from './documentsLiveAuth';

let verifyDocumentEditToken = vi.hoisted(() => vi.fn());
let getDocumentById = vi.hoisted(() => vi.fn());
let getDocumentPermissions = vi.hoisted(() => vi.fn());
let resolveCargoAccess = vi.hoisted(() => vi.fn());

vi.mock('@metorial/module-documents', () => ({
  documentEditTokenService: { verifyDocumentEditToken },
  documentService: { getDocumentById, getDocumentPermissions }
}));
vi.mock('@metorial/module-file', () => ({ resolveCargoAccess }));
vi.mock('@metorial/db', () => ({
  db: {
    consumerProfile: {
      findFirst: vi.fn()
    }
  }
}));
vi.mock('@metorial/module-access', () => ({
  createResourceAuthorization: vi.fn()
}));

describe('documents live token authorization', () => {
  it('intersects signed capabilities with current document permissions', async () => {
    let owner = {
      type: 'instance',
      organization: { id: 'org_123' },
      instance: { id: 'inst_123', oid: 1n }
    } as any;
    let authorization = { type: 'privileged', resourceActor: { id: 'rac_123' } };
    verifyDocumentEditToken.mockResolvedValue({
      owner,
      documentId: 'doc_123',
      instanceId: 'inst_123',
      organizationId: 'org_123',
      expiresAt: new Date('2030-01-01T00:00:00Z'),
      permissions: ['content_read', 'content_write'],
      accessTags: [],
      accessActor: { name: 'Member', resourceActorId: 'rac_123' },
      defaultPermissions: [],
      overridePermissions: false
    });
    resolveCargoAccess.mockResolvedValue({
      actor: { id: 'rac_123', consumerProfileOid: null },
      actorId: 'rac_123',
      authorization,
      scope: { project: { oid: 3n }, instance: { oid: 1n } }
    });
    getDocumentById.mockResolvedValue({ id: 'doc_123', isReadOnly: false });
    getDocumentPermissions.mockResolvedValue({
      hasFullAccess: false,
      permissions: ['content_read']
    });

    let target = await resolveDocumentsLiveToken({
      editToken: 'document_edit_token',
      documentId: 'doc_123',
      instanceId: 'inst_123',
      context: { ip: '127.0.0.1', ua: 'test' }
    });

    expect(target.permissions).toEqual(['content_read']);
    expect(target.actorId).toBe('rac_123');
    expect(target.authorization).toBe(authorization);
  });

  it('rejects a token when current read access has been removed', async () => {
    getDocumentPermissions.mockResolvedValue({
      hasFullAccess: false,
      permissions: []
    });

    await expect(
      resolveDocumentsLiveToken({
        editToken: 'document_edit_token',
        documentId: 'doc_123',
        instanceId: 'inst_123',
        context: { ip: '127.0.0.1', ua: 'test' }
      })
    ).rejects.toThrow('does not grant read access');
  });
});
